<script setup lang="ts">
import { computed, nextTick, onUnmounted, ref } from 'vue';
import { Activity, ArrowUpRight, ChevronRight, Clock3, Database, Globe2, RefreshCw, Server, ShieldCheck, ShieldAlert, X } from 'lucide-vue-next';
import { t, locale } from './i18n';
import CountryMark from './CountryMark.vue';
import type { IPQuality, QualityTag } from './quality';
const props=defineProps<{value?:IPQuality;name:string;running?:boolean;readOnly?:boolean}>();
const emit=defineEmits<{run:[]}>();
const open=ref(false),dialog=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null);
const section=ref('overview');
const legacyLabels:Record<string,string>={'疑似家宽 / 运营商':'ISP 运营商网络','疑似原生 IP':'注册与定位国家一致','疑似广播 IP':'注册与定位国家不一致','数据中心倾向':'网络类型未确认','家宽类型未知':'未识别网络类型','原生 / 广播未知':'注册与定位对照未知','Netflix · 解锁迹象':'Netflix · 目录可达','YouTube Premium · 可订阅迹象':'YouTube Premium · 订阅入口可达'};
const normalize=(tag:QualityTag):QualityTag=>({...tag,label:legacyLabels[tag.label]||tag.label,status:tag.status==='likely'?'info':tag.status});
const identity=computed(()=>(props.value?.tags||[]).map(normalize));
const signals=computed(()=>(props.value?.signals||[]).map(normalize));
const services=computed(()=>[...(props.value?.ai||[]),...(props.value?.streams||[])].map(normalize));
const providers=computed(()=>props.value?.providers||[]);
const available=computed(()=>providers.value.filter(p=>p.status==='ok').length);
const scores=computed(()=>providers.value.flatMap(p=>(p.risk_scores||[]).map(s=>({...s,provider:p.name}))));
const scoreName=(name:string)=>t(({'ProxyCheck risk score':'风险评分','ProxyCheck detection confidence':'检测置信度','Net.Coffee trust score':'信任评分','Net.Coffee abuse score':'滥用评分','ASN abuse score':'ASN 滥用评分','Company abuse score':'机构滥用评分'} as Record<string,string>)[name]||name);
const riskKeys=['vpn','proxy','tor','abuse'];
const riskCount=computed(()=>signals.value.filter(s=>riskKeys.includes(s.key)&&s.status==='info').length);
const riskTitle=computed(()=>riskCount.value?t('存在风险标记'):signals.value.some(s=>riskKeys.includes(s.key)&&s.status==='conflict')?t('风险标记有分歧'):signals.value.filter(s=>riskKeys.includes(s.key)&&s.status==='clean').length===riskKeys.length?t('未检出风险标记'):t('风险数据待补充'));
const summary=computed(()=>[...identity.value.filter(s=>s.key==='network'||s.key==='native'),...signals.value.filter(s=>riskKeys.includes(s.key)&&['info','conflict'].includes(s.status)).slice(0,2),...services.value.filter(s=>s.key==='netflix')].slice(0,5));
const time=computed(()=>props.value?.at?new Date(props.value.at*1000).toLocaleString(locale.value):t('尚未检测'));
const isLegacy=computed(()=>!!props.value&&(props.value.schema_version||0)<4);
const signalName=(key:string)=>t(({hosting:'托管网络',vpn:'VPN',proxy:'代理',tor:'Tor',crawler:'爬虫',abuse:'滥用记录',residential:'住宅网络标记',broadcast:'广播属性标记',mobile:'移动网络标记',compromised:'受控设备标记',anonymous:'匿名网络标记'} as Record<string,string>)[key]||key);
const rpkiLabel=(status:string)=>t(({valid:'有效（valid）',invalid:'无效（invalid）','not-found':'未找到（not-found）'} as Record<string,string>)[status]||status);
const serviceName=(key:string)=>({netflix:'Netflix',disney:'Disney+',youtube:'YouTube Premium',claude:'Claude',anthropic:'Anthropic',openai:'OpenAI'} as Record<string,string>)[key]||key;
const evidence=(value:string)=>{let out=t(value);if(locale.value!=='en'||out!==value)return out;for(const part of ['RIR 注册国家 ','，出口地理国家 ','；这是国家对照结果，不代表物理接入位置或 BGP 宣告性质','；仅表示这些数据库当前未标记','返回 true 的提供方：','返回 false 的提供方：','标记来源：','；未标记来源：','；页面仅读取预算内的内容'])out=out.replace(part,t(part));return out};
const serviceStatus=(tag:QualityTag)=>t(tag.label).split(' · ').slice(1).join(' · ')||t(tag.label);
const country=(code?:string)=>{if(!code)return t('未知');try{return new Intl.DisplayNames([locale.value],{type:'region'}).of(code.toUpperCase())||code}catch{return code}};
const localZone=Intl.DateTimeFormat().resolvedOptions().timeZone;
const info=computed(()=>[
 [t('地区'),country(props.value?.country_code)],
 [t('城市 / 区域'),[props.value?.city,props.value?.region].filter(Boolean).join(' / ')||t('未知')],
 ['ASN',props.value?.asn||t('未知')],
 [t('运营商 / 机构'),props.value?.organization||t('未知')],
 [t('地址段'),props.value?.network_cidr||t('未知')],
 [t('注册国家'),country(props.value?.registered_country)],
 [t('出口时区'),props.value?.timezone||t('未知')],
 [t('浏览器时区'),localZone],
]);
const tabs=computed(()=>[{id:'overview',label:t('检测总览')},{id:'services',label:t('流媒体与 AI')},{id:'providers',label:t('数据源对照')}]);
async function show(){open.value=true;section.value='overview';await nextTick();dialog.value?.focus()}
function close(){open.value=false;nextTick(()=>trigger.value?.focus())}
function keydown(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'&&dialog.value){const items=Array.from(dialog.value.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input,select,textarea,summary,[tabindex="0"]')).filter(el=>el.offsetParent!==null);const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
onUnmounted(()=>{open.value=false});
</script>
<template>
 <button ref="trigger" class="quality-summary" :aria-label="t('查看 IP 质量 ')+name" @click="show">
  <span v-if="!value" class="quality-chip unknown"><ShieldCheck :size="12"/>{{t('质量待检测')}}</span>
  <span v-for="tag in summary" :key="tag.key" :class="['quality-chip',tag.status]">{{t(tag.label)}}</span>
  <span v-if="value?.error" class="quality-chip unknown">{{t('待复测')}}</span>
  <span class="quality-more">{{t('质量报告')}}<ChevronRight :size="11"/></span>
 </button>
 <Teleport to="body"><div v-if="open" class="qi-overlay" @click.self="close"><section ref="dialog" class="qi-dialog" role="dialog" aria-modal="true" :aria-label="t('IP 质量 · ')+name" tabindex="-1" @keydown="keydown">
  <header class="qi-header"><div><span class="qi-eyebrow">IP INTELLIGENCE</span><h2>{{t('IP 质量报告')}}</h2><p>{{name}}</p></div><div class="qi-header-actions"><button v-if="!readOnly" class="primary" :disabled="running" @click="emit('run')"><RefreshCw :size="14" :class="{spin:running}"/>{{running?t('检测中…'):t('重新检测')}}</button><button class="icon" :aria-label="t('关闭质量详情')" @click="close"><X :size="20"/></button></div></header>
  <div class="qi-tabs" role="tablist" :aria-label="t('质量报告分区')"><button v-for="tab in tabs" :key="tab.id" role="tab" :aria-selected="section===tab.id" :class="{selected:section===tab.id}" @click="section=tab.id">{{tab.label}}<span v-if="tab.id==='providers'">{{available}} / {{providers.length}}</span></button></div>
  <div class="qi-body">
   <p v-if="value?.error" class="qi-notice" role="status">{{t(value.error)}}</p><p v-if="isLegacy" class="qi-notice">{{t(readOnly?'历史报告等待管理员或后台更新。':'历史检测记录，请重新检测补充安全与地区信息。')}}</p>
   <div v-if="!value" class="qi-empty"><ShieldCheck :size="38"/><h3>{{t(readOnly?'质量报告尚未生成':'建立这条出口的质量档案')}}</h3><p>{{t(readOnly?'管理员完成检测后，这里会展示已保存的质量结果。':'从所选出口检测服务可达性，并汇总地理、网络与安全数据。')}}</p><button v-if="!readOnly" class="primary" :disabled="running" @click="emit('run')">{{running?t('检测中…'):t('开始检测')}}</button></div>
   <template v-else>
    <div class="qi-identity"><CountryMark :code="value.country_code" :country="country(value.country_code)"/><div><span>{{t('已检测出口 IP')}}</span><strong>{{value.ip||t('出口待确认')}}</strong><p>{{country(value.country_code)}}<span v-if="value.city"> · {{value.city}}</span> · {{value.asn||t('ASN 待识别')}}</p></div><span class="qi-observed"><Clock3 :size="12"/>{{time}}</span></div>
    <template v-if="section==='overview'">
     <div class="qi-top-grid"><article class="qi-card qi-risk"><header><h3><ShieldCheck :size="16"/>{{t('风险情报')}}</h3><span :class="['quality-chip',riskCount?'blocked':'info']">{{riskTitle}}</span></header><div class="qi-risk-value"><strong>{{riskCount}}</strong><span>{{t('项风险标记')}}</span></div><p>{{t('基于数据源明确返回的 VPN、代理、Tor 与滥用标记。')}}</p><div class="qi-coverage"><span>{{t('可用数据源')}}</span><b>{{available}} / {{providers.length}}</b></div><div class="qi-coverage-bar"><i :style="{width:(providers.length?available/providers.length*100:0)+'%'}"/></div><small>{{t('数据覆盖率不等于 IP 信誉评分。')}}</small><div v-for="score in scores" :key="score.provider+score.name" class="qi-score"><span>{{score.provider}} · {{scoreName(score.name)}}</span><strong>{{score.value}} <small>{{score.scale}}</small></strong><p>{{score.label}}</p></div></article>
      <article class="qi-card qi-attributes"><header><h3><Globe2 :size="16"/>{{t('出口属性')}}</h3></header><dl><div v-for="[label,value] in info" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></div></dl></article></div>
     <article class="qi-card"><header><h3><Server :size="16"/>{{t('网络身份')}}</h3></header><div class="qi-facts"><div v-for="tag in identity" :key="tag.key"><span :class="['quality-chip',tag.status]">{{t(tag.label)}}</span><p>{{evidence(tag.evidence)}}</p></div></div></article>
     <article class="qi-card"><header><h3><ShieldAlert :size="16"/>{{t('安全标记')}}</h3><span class="qi-caption">{{t('未返回的数据保留未知')}}</span></header><div class="qi-signals"><div v-for="key in ['hosting','vpn','proxy','tor','crawler','abuse']" :key="key"><strong>{{signalName(key)}}</strong><span :class="['quality-chip',signals.find(s=>s.key===key)?.status||'unknown']">{{signals.find(s=>s.key===key)?t(signals.find(s=>s.key===key)!.label):t('未知')}}</span><p>{{evidence(signals.find(s=>s.key===key)?.evidence||'数据源未提供此项')}}</p></div></div></article>
     <button class="qi-next" @click="section='services'">{{t('查看流媒体与 AI 检测')}}<ArrowUpRight :size="15"/></button>
    </template>
    <template v-else-if="section==='services'"><article class="qi-card"><header><h3><Activity :size="16"/>{{t('流媒体与 AI 服务')}}</h3><span class="qi-caption">{{t('通过所选出口实时请求')}}</span></header><div class="qi-services"><article v-for="item in services" :key="item.key"><div class="qi-service-head"><span class="qi-service-icon">{{serviceName(item.key).slice(0,1)}}</span><h4>{{serviceName(item.key)}}</h4><span :class="['quality-chip',item.status]">{{serviceStatus(item)}}</span></div><p>{{evidence(item.evidence)}}</p><footer><span>{{item.http_status?'HTTP '+item.http_status:t('无有效响应')}}</span><span>{{item.latency_ms?item.latency_ms+' ms':'—'}}</span></footer></article></div><p class="qi-method">{{t('页面、目录或订阅入口可达只确认对应请求；账户登录、付费播放和模型调用需分别验证。')}}</p></article></template>
    <template v-else><article class="qi-card"><header><h3><Database :size="16"/>{{t('多方数据对照')}}</h3><span class="qi-caption">{{t('各来源独立展示，冲突不会被隐藏')}}</span></header><div class="qi-provider-scroll"><table class="qi-provider-table"><thead><tr><th>{{t('数据源')}}</th><th>{{t('状态')}}</th><th>{{t('国家 / 城市')}}</th><th>ASN / {{t('机构')}}</th><th>{{t('网络分类')}}</th><th>{{t('查询时间')}}</th></tr></thead><tbody><tr v-for="provider in providers" :key="provider.name"><td><strong>{{provider.name}}</strong><small>{{t(provider.cached?'缓存结果':'本次查询')}}</small></td><td><span :class="['quality-chip',provider.status==='ok'?'clean':'unknown']">{{provider.status==='ok'?t('可用'):t('不可用')}}</span><small v-if="provider.error">{{t(provider.error)}}</small></td><td>{{provider.country_code?country(provider.country_code):provider.country||'—'}}<small>{{[provider.city,provider.region].filter(Boolean).join(' / ')||'—'}}</small></td><td>{{provider.asn||'—'}}<small>{{provider.organization||'—'}}</small></td><td>{{provider.network?.label?t(normalize(provider.network).label):'—'}}<small>{{provider.network_cidr||'—'}}</small></td><td>{{new Date(provider.at*1000).toLocaleString(locale)}}</td></tr></tbody></table></div><div class="qi-provider-signals"><details v-for="provider in providers.filter(p=>Object.keys(p.signals||{}).length||p.rpki_status)" :key="provider.name"><summary>{{provider.name}} · {{t('原始安全标记')}}</summary><div><span v-for="(value,key) in provider.signals" :key="key" :class="['quality-chip',value===true?'info':value===false?'clean':'unknown']">{{signalName(String(key))}} · {{value===true?t('已标记'):value===false?t('未标记'):t('未知')}}</span></div><section v-if="provider.rpki_status" class="qi-provider-rpki"><div><strong>{{t('提供方 RPKI 状态')}}</strong><span :class="['quality-chip',provider.rpki_status==='invalid'?'conflict':provider.rpki_status==='valid'?'clean':'unknown']">{{rpkiLabel(provider.rpki_status)}}</span></div><p>{{t('此结果由提供方报告，仅涉及路由授权验证，不能证明 IP 原生、广播或住宅属性；未独立验证 BGP 宣告。')}}</p></section></details></div><p class="qi-method">{{t('地理与风险元数据按出口 IP 缓存，展示各自查询时间；服务可达性每次从所选出口重新检测。')}}</p></article></template>
   </template>
  </div><footer class="qi-footer"><span><ShieldCheck :size="13"/>{{t('结果对应本次出口 IP 与检测时间')}}</span><span>{{t('公共 / 私有资源独立管理')}}</span></footer>
 </section></div></Teleport>
</template>
<style>
.qi-provider-rpki{margin-top:13px;padding-top:12px;border-top:1px solid var(--border)}.qi-provider-rpki>div{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:9px}.qi-provider-rpki strong{font-size:10px;font-weight:500}.qi-provider-rpki p{margin:9px 0 0;font-size:10px;overflow-wrap:anywhere}

.quality-summary{display:flex!important;flex-wrap:wrap;align-items:center;gap:5px!important;padding:7px 0 0!important;border:0!important;background:transparent!important;text-align:left;box-shadow:none!important;white-space:normal!important;max-width:350px}.quality-chip{display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border-radius:5px;font-size:10px;font-weight:500;line-height:1.4;background:var(--surface-raised);color:var(--muted)}.quality-chip.confirmed,.quality-chip.info,.quality-chip.page{background:#787fe324;color:#a4abff}.quality-chip.clean{background:#14b8a620;color:#42c9b3}.quality-chip.blocked,.quality-chip.conflict{background:#ef667921;color:#f0909c}.quality-more{display:inline-flex;align-items:center;font-size:10px;color:var(--accent-text);padding:3px 0}.qi-overlay{position:fixed;inset:0;z-index:140;display:flex;align-items:center;justify-content:center;background:#020812b8;backdrop-filter:blur(5px);padding:24px}.qi-dialog{width:min(1060px,100%);max-height:94dvh;display:flex;flex-direction:column;background:var(--bg,var(--surface));border:1px solid var(--border);border-radius:16px;box-shadow:0 25px 90px #0005;outline:none;overflow:hidden;color:var(--text)}.qi-header{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:24px 28px;background:var(--surface);flex-shrink:0}.qi-header h2{font-size:22px;margin:6px 0;letter-spacing:-.03em}.qi-eyebrow{font-size:9px;color:var(--accent-text);letter-spacing:.15em}.qi-header p{font-size:11px;color:var(--muted);margin:0;overflow-wrap:anywhere}.qi-header-actions{display:flex;gap:12px;align-items:center;flex-shrink:0}.qi-header-actions button{font-size:11px}.qi-tabs{display:flex;gap:22px;padding:0 28px;border-bottom:1px solid var(--border);background:var(--surface);flex-shrink:0}.qi-tabs button{background:transparent;border:0;border-bottom:2px solid transparent;border-radius:0;padding:13px 0;color:var(--muted);font-size:12px;gap:8px}.qi-tabs button.selected{color:var(--accent-text)